import { NextResponse } from "next/server";
import { prisma } from "@/src/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/app/api/auth/[...nextauth]/route";

export async function GET() {
  const session = await getServerSession(authOptions);
  if (!session?.user) return NextResponse.json({ backlog: [], sprint: [], todo: [], progress: [], done: [] });
  const items = await prisma.scrumItem.findMany({ where: { userId: (session.user as any).id } });
  const columns: any = { backlog: [], sprint: [], todo: [], progress: [], done: [] };
  items.forEach(item => columns[item.columnId]?.push(item.title));
  return NextResponse.json(columns);
}

export async function POST(req: Request) {
  const session = await getServerSession(authOptions);
  const { title, columnId } = await req.json();
  const newItem = await prisma.scrumItem.create({ data: { title, columnId, userId: (session.user as any).id } });
  return NextResponse.json(newItem);
}

export async function PATCH(req: Request) {
  const session = await getServerSession(authOptions);
  const { title, newColumnId, newTitle } = await req.json();
  await prisma.scrumItem.updateMany({
    where: { title, userId: (session.user as any).id },
    data: { columnId: newColumnId || undefined, title: newTitle || undefined }
  });
  return NextResponse.json({ success: true });
}

export async function DELETE(req: Request) {
  const session = await getServerSession(authOptions);
  const { title } = await req.json();
  await prisma.scrumItem.deleteMany({ where: { title, userId: (session.user as any).id } });
  return NextResponse.json({ success: true });
}